//! `AET-WO-3401` §1.3, tier 1: Sentinel-01 as ordered ("V0+",
//! `examples/sentinel-01.json`) has a board directory of its own,
//! `boards/sentinel-01-bench/`, so the reference (`sentinel-01-minimal.json`,
//! `boards/sentinel-01/`) stays P1's byte-for-byte fixture. The directory is
//! regenerated by `aethelgard-svd-hal/tests/board.rs`, as the reference's is.
//! Here: the specification validates, so its acknowledgements name exactly
//! the ledger's rows, the EXT bus's I2C2 rows included (`generate` does not
//! check them; `validate` and `verify` do).

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde_json::Value;

const SPEC: &str = "examples/sentinel-01.json";

fn root() -> PathBuf {
    fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")).unwrap()
}

/// Runs the binary from the repository root with an empty `PATH`:
/// `validate` starts no tool.
fn run(args: &[&str]) -> (Option<i32>, Value) {
    let out = Command::new(env!("CARGO_BIN_EXE_aethelgard"))
        .args(args)
        .current_dir(root())
        .stdin(Stdio::null())
        .env("PATH", "")
        .output()
        .unwrap();
    let stdout = String::from_utf8(out.stdout).unwrap();
    assert_eq!(stdout.lines().count(), 1, "{args:?}: {stdout}");
    (out.status.code(), serde_json::from_str(&stdout).unwrap())
}

#[test]
fn the_ordered_board_validates() {
    let (code, v) = run(&["validate", "--file", SPEC]);
    assert_eq!(code, Some(0), "{v}");
    assert_eq!(v["project_name"], "sentinel-01-bench", "{v}");
}
